import{_ as d,o as a,c as t,a3 as s}from"./chunks/framework.CCylkYel.js";const m=JSON.parse('{"title":"Racks and devices","description":"","frontmatter":{},"headers":[],"relativePath":"developers/commands/racks.md","filePath":"developers/commands/racks.md"}'),c={name:"developers/commands/racks.md"};function o(n,e,r,i,p,l){return a(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="racks-and-devices" tabindex="-1">Racks and devices <a class="header-anchor" href="#racks-and-devices" aria-label="Permalink to &quot;Racks and devices&quot;">​</a></h1><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>s32 --loopback repl</span></span>
<span class="line"><span>s32&gt; rack list</span></span>
<span class="line"><span>s32&gt; rack rename 0 Lead</span></span>
<span class="line"><span>s32&gt; device add 0 step-seq</span></span>
<span class="line"><span>s32&gt; device list 0</span></span>
<span class="line"><span>s32&gt; stepseq set 0 1 step 0 active=1 note=60 vel=100</span></span>
<span class="line"><span>s32&gt; stepseq get 0 1</span></span>
<span class="line"><span>s32&gt; rack duplicate 0 1</span></span>
<span class="line"><span>s32&gt; rack bypass 1 on</span></span></code></pre></div><p><code>RACK</code> and <code>DEV</code> are positions: rack <code>0</code> is the first <a href="/racks/">rack</a>, device <code>0</code> the first device in it. Ids (<code>rack list</code>, <code>device list</code>) are used only by <code>lfo assign</code> and <code>macro set … mode=device</code>.</p><h2 id="racks" tabindex="-1">Racks <a class="header-anchor" href="#racks" aria-label="Permalink to &quot;Racks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>rack list</code></td><td>Position, id, bypass, device count and name of each rack. An empty slot&#39;s id prints <code>-</code></td></tr><tr><td><code>rack rename RACK NAME</code></td><td>Keeps the first 10 characters</td></tr><tr><td><code>rack bypass RACK on|off</code></td><td></td></tr><tr><td><code>rack clear RACK</code></td><td>Asks first. Removes every device</td></tr><tr><td><code>rack duplicate SRC DST</code></td><td></td></tr></tbody></table><h2 id="devices" tabindex="-1">Devices <a class="header-anchor" href="#devices" aria-label="Permalink to &quot;Devices&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>device list RACK</code></td><td>Position, type, id and name of each device</td></tr><tr><td><code>device add RACK TYPE</code></td><td>Adds a <a href="/devices/">device</a> to the rack. <code>TYPE</code> is a name (<code>midi-in</code>, <code>midi-out</code>, <code>clock</code>, <code>arp</code>, <code>step-seq</code>, …) or its number from <code>schema</code></td></tr><tr><td><code>device remove RACK DEV</code></td><td></td></tr><tr><td><code>device move RACK FROM TO</code></td><td>Reorders inside the rack. MIDI IN stays first, MIDI OUT last</td></tr><tr><td><code>device param get RACK DEV PARAM</code></td><td>Value and range</td></tr><tr><td><code>device param set RACK DEV PARAM VALUE</code></td><td>Rounded to a whole number and clamped to the range</td></tr></tbody></table><p>An empty rack takes <strong>MIDI IN</strong> or <strong>CLOCK</strong> first. A device that can&#39;t go there, or a full rack, answers <code>BadRequest</code>. <code>NoSpace</code> means the S32 has no room for another device.</p><p><code>PARAM</code> is a parameter name (<code>bypass</code>, <code>mode</code>, <code>rate</code>, <code>gate</code>, <code>clock-division</code>, …) or its number from <code>schema</code>, not the row on the screen.</p><p>IN SNAPSHOT and ALLOW MORPH for device parameters are under <a href="./snapshots#in-snapshot"><code>snapshot flags</code></a>.</p><h2 id="step-seq" tabindex="-1">Step Seq <a class="header-anchor" href="#step-seq" aria-label="Permalink to &quot;Step Seq&quot;">​</a></h2><p><code>stepseq get RACK DEV</code> prints all 16 steps. <code>DEV</code> must be a Step Seq.</p><p><code>stepseq set RACK DEV step N key=value …</code> changes one step (<code>0</code>–<code>15</code>). Keys: <code>active</code>, <code>note</code>, <code>vel</code>, <code>gate</code>, <code>ch</code>, <code>prob</code>.</p>`,13)])])}const v=d(c,[["render",o]]);export{m as __pageData,v as default};
